import React from "react";

export function TailwindflexByOmerlink2() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="fr" class="dark">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Omer Dashboard Pro</title>

    <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;600;800&display=swap" rel="stylesheet">

    <style>
        body {
            background-color: #050505;
            color: #fff;
            font-family: 'Plus Jakarta Sans', sans-serif;
            overflow-x: hidden;
        }

        /* --- EFFET DE LUMIÈRE SUIVEUSE --- */
        .mouse-glow {
            position: fixed;
            width: 600px;
            height: 600px;
            background: radial-gradient(circle, rgba(22, 163, 74, 0.15) 0%, rgba(0,0,0,0) 70%);
            border-radius: 50%;
            pointer-events: none;
            z-index: 0;
            transform: translate(-50%, -50%);
            transition: opacity 0.3s;
        }

        /* --- GLASSMORPHISM LIQUIDE --- */
        .glass-nav {
            background: rgba(15, 15, 15, 0.6);
            backdrop-filter: blur(20px) saturate(180%);
            border: 1px solid rgba(255, 255, 255, 0.08);
        }

        /* --- PROFIL LUMINEUX --- */
        .profile-glow {
            position: relative;
        }
        .profile-glow::after {
            content: '';
            position: absolute;
            inset: -5px;
            background: linear-gradient(45deg, #16a34a, #22c55e, #4ade80);
            border-radius: 24px;
            z-index: -1;
            filter: blur(15px);
            opacity: 0.6;
            animation: pulse-glow 3s infinite alternate;
        }

        @keyframes pulse-glow {
            0% { opacity: 0.4; transform: scale(0.95); }
            100% { opacity: 0.8; transform: scale(1.05); }
        }

        /* --- BOUTONS FLOTTANTS --- */
        .float-btn {
            transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
        }
        .float-btn:hover {
            transform: translateY(-5px) scale(1.05);
            box-shadow: 0 10px 20px rgba(22, 163, 74, 0.3);
        }

        .card-modern {
            background: rgba(255, 255, 255, 0.03);
            border: 1px solid rgba(255, 255, 255, 0.05);
            transition: all 0.3s ease;
        }
        .card-modern:hover {
            background: rgba(255, 255, 255, 0.06);
            border-color: rgba(22, 163, 74, 0.4);
        }
    </style>
</head>
<body class="antialiased">

    <div id="glow" class="mouse-glow"></div>

    <nav class="fixed top-6 left-1/2 -translate-x-1/2 z-50 w-[95%] max-w-5xl">
        <div class="glass-nav rounded-2xl px-6 py-3 flex justify-between items-center shadow-2xl">
            <div class="flex items-center gap-2">
                <div class="w-8 h-8 bg-green-600 rounded-lg flex items-center justify-center font-bold">T</div>
                <span class="font-extrabold tracking-tighter text-xl">Tailwind<span class="text-green-500">Flex</span></span>
            </div>

            <div class="hidden md:flex gap-6 items-center">
                <a href="#" class="text-sm font-medium text-gray-400 hover:text-white transition">Dashboard</a>
                <a href="#" class="text-sm font-medium text-gray-400 hover:text-white transition">Components</a>
                <a href="#" class="text-sm font-medium text-gray-400 hover:text-white transition">Showcase</a>
            </div>

            <div class="flex items-center gap-4">
                <button class="p-2 text-gray-400 hover:text-white">
                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
                </button>
                <div class="w-10 h-10 rounded-full bg-gradient-to-tr from-green-400 to-green-700 p-[2px]">
                    <img src="https://lh3.googleusercontent.com/a/ACg8ocKtpueB00ZdmmbwHuEtYEPdrXJPJfNiBWQk1dOtCeuvGkNyEfyz=s96-c" class="w-full h-full rounded-full object-cover border-2 border-black" alt="Profile">
                </div>
            </div>
        </div>
    </nav>


    <button class="fixed bottom-8 right-8 w-16 h-16 bg-green-600 rounded-full flex items-center justify-center shadow-[0_0_30px_rgba(22,163,74,0.5)] float-btn z-50">
        <svg class="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M12 4v16m8-8H4"></path></svg>
    </button>


</body>
</html>" }} />
  );
}
